    (30, 'bdd568d3-3a54-442a-9f8c-af7ac07bbaf0'::uuid, 'Pendeen Vau Fogou - geograph.org.uk - 8396481.webp', 'https://upload.wikimedia.org/wikipedia/commons/6/67/Pendeen_Vau_Fogou_-_geograph.org.uk_-_8396481.jpg', 'https://commons.wikimedia.org/wiki/File%3APendeen%20Vau%20Fogou%20-%20geograph.org.uk%20-%208396481.jpg', 'Pendeen Vau Fogou - geograph.org.uk - 8396481', 'Chris Andrews', 'https://www.geograph.org.uk/profile/16152', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 1600, 1066, 306276, NULL, NULL, '/data/images/wiki/bdd568d3/Pendeen Vau Fogou - geograph.org.uk - 8396481.webp', 'import-hero/insert:bdd568d3-3a54-442a-9f8c-af7ac07bbaf0', 'a model looked at every Commons candidate of this site and judged this file ''depicts'' - a picture of the site itself - while the site showed nothing at all: no gallery row and no thumbnail_url (owner decision 2026-10-06)', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/6/67/Pendeen_Vau_Fogou_-_geograph.org.uk_-_8396481.jpg", "source": "the candidate search''s confirmed verdict (candidate_search/VERDICTS.jsonl)", "url": "https://commons.wikimedia.org/wiki/File%3APendeen%20Vau%20Fogou%20-%20geograph.org.uk%20-%208396481.jpg"}, {"quote": "1 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/6/67/Pendeen_Vau_Fogou_-_geograph.org.uk_-_8396481.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = bdd568d3-3a54-442a-9f8c-af7ac07bbaf0"}]'::jsonb),
    (31, 'be26197d-61ab-4221-83d9-d43be9976e33'::uuid, 'Pièce pressoir archmus Eretria Greece.webp', 'https://upload.wikimedia.org/wikipedia/commons/8/88/Pi%C3%A8ce_pressoir_archmus_Eretria_Greece.jpg', 'https://commons.wikimedia.org/wiki/File%3APi%C3%A8ce%20pressoir%20archmus%20Eretria%20Greece.jpg', 'Pièce pressoir archmus Eretria Greece', 'Jebulon', 'https://commons.wikimedia.org/wiki/User:Jebulon', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', 1600, 1067, 543820, NULL, NULL, '/data/images/wiki/be26197d/Pièce pressoir archmus Eretria Greece.webp', 'import-hero/insert:be26197d-61ab-4221-83d9-d43be9976e33', 'a model looked at every Commons candidate of this site and judged this file ''depicts'' - a picture of the site itself - while the site showed nothing at all: no gallery row and no thumbnail_url (owner decision 2026-10-06)', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/8/88/Pi%C3%A8ce_pressoir_archmus_Eretria_Greece.jpg", "source": "the candidate search''s confirmed verdict (candidate_search/VERDICTS.jsonl)", "url": "https://commons.wikimedia.org/wiki/File%3APi%C3%A8ce%20pressoir%20archmus%20Eretria%20Greece.jpg"}, {"quote": "1 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/8/88/Pi%C3%A8ce_pressoir_archmus_Eretria_Greece.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = be26197d-61ab-4221-83d9-d43be9976e33"}]'::jsonb),
    (32, 'bff9c3d8-4897-417b-9ef1-0bd7aae62826'::uuid, 'Anavarza castle 2775.webp', 'https://upload.wikimedia.org/wikipedia/commons/5/58/Anavarza_castle_2775.jpg', 'https://commons.wikimedia.org/wiki/File%3AAnavarza%20castle%202775.jpg', 'Anavarza castle 2775', 'Dosseman', 'https://commons.wikimedia.org/wiki/User:Dosseman', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 1600, 1062, 314480, NULL, NULL, '/data/images/wiki/bff9c3d8/Anavarza castle 2775.webp', 'import-hero/insert:bff9c3d8-4897-417b-9ef1-0bd7aae62826', 'a model looked at every Commons candidate of this site and judged this file ''depicts'' - a picture of the site itself - while the site showed nothing at all: no gallery row and no thumbnail_url (owner decision 2026-10-06)', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/5/58/Anavarza_castle_2775.jpg", "source": "the candidate search''s confirmed verdict (candidate_search/VERDICTS.jsonl)", "url": "https://commons.wikimedia.org/wiki/File%3AAnavarza%20castle%202775.jpg"}, {"quote": "0 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/5/58/Anavarza_castle_2775.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = bff9c3d8-4897-417b-9ef1-0bd7aae62826"}]'::jsonb),
    (33, 'c04b9633-ab16-45bf-b36b-18f83096f46f'::uuid, 'Yeni-Kale (20).webp', 'https://upload.wikimedia.org/wikipedia/commons/6/68/Yeni-Kale_%2820%29.jpg', 'https://commons.wikimedia.org/wiki/File%3AYeni-Kale%20%2820%29.jpg', 'Yeni-Kale (20)', 'Dmytro Petishkin', 'https://commons.wikimedia.org/wiki/User:Mit31051968', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0', 1600, 1067, 430230, NULL, NULL, '/data/images/wiki/c04b9633/Yeni-Kale (20).webp', 'import-hero/insert:c04b9633-ab16-45bf-b36b-18f83096f46f', 'a model looked at every Commons candidate of this site and judged this file ''depicts'' - a picture of the site itself - while the site showed nothing at all: no gallery row and no thumbnail_url (owner decision 2026-10-06)', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/6/68/Yeni-Kale_%2820%29.jpg", "source": "the candidate search''s confirmed verdict (candidate_search/VERDICTS.jsonl)", "url": "https://commons.wikimedia.org/wiki/File%3AYeni-Kale%20%2820%29.jpg"}, {"quote": "20 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/6/68/Yeni-Kale_%2820%29.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = c04b9633-ab16-45bf-b36b-18f83096f46f"}]'::jsonb);

DO $$
DECLARE
    bad  integer;
    r    RECORD;
    new_id integer;
    cols TEXT;
BEGIN
    -- guard 1: every planned site is a curated site (the message names the source in words, so
    -- the log of a refused wave says what was expected)
    SELECT count(*) INTO bad FROM (SELECT DISTINCT site_id FROM _ih_insert) p
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % planned site(s) are not ancient_nerds sites',
            'insert-2026-10-07-006-001', bad;
    END IF;

    FOR r IN SELECT * FROM _ih_insert ORDER BY seq LOOP
        -- guard 2: no row of this site holds the file yet. The unique constraint on
        -- (site_id, original_url) is a second line of defence behind this one.
        IF EXISTS (SELECT 1 FROM wiki_images w
                    WHERE w.site_id = r.site_id AND w.original_url = r.original_url) THEN
            RAISE EXCEPTION '%: site % already holds this file', r.change_key, r.site_id;
        END IF;

        -- guard 3: the file reaches the hero floor
        IF r.width < 1600 OR r.height < 900 THEN
            RAISE EXCEPTION '%: the file is %x%, under the %x% this lane serves', r.change_key,
                r.width, r.height, 1600, 900;
        END IF;

        -- guard 4: the row that holds the flag is still the one the plan demotes
        IF r.demoted_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM wiki_images w
             WHERE w.id = r.demoted_id AND w.site_id = r.site_id AND w.is_hero) THEN
            RAISE EXCEPTION '%: the row that held the flag for site % moved since the read',
                r.change_key, r.site_id;
        END IF;

        -- guard 5: the thumbnail still holds the value the read found
        IF (SELECT u.thumbnail_url FROM unified_sites u WHERE u.id = r.site_id)
           IS DISTINCT FROM r.old_thumbnail THEN
            RAISE EXCEPTION '%: the thumbnail of site % moved since the read', r.change_key, r.site_id;
        END IF;

        -- the row that gives up the flag, and the row that takes it
        IF r.demoted_id IS NOT NULL THEN
            UPDATE wiki_images SET is_hero = false
             WHERE id = r.demoted_id AND is_hero AND site_id = r.site_id;
        END IF;

        -- the three columns the file does not carry: the next free number of this site (derived,
        -- never invented), the owner's picture rather than a measured lead image of the article,
        -- and the source 49,683 of the 49,691 curated rows carry
        INSERT INTO wiki_images
            (site_id, filename, original_url, commons_page_url, title, author, author_url, license, license_url, width, height, file_size_bytes, is_lead, sort_order, source_type, is_hero, is_excluded)
        SELECT r.site_id, r.filename, r.original_url, r.commons_page_url, r.title, r.author, r.author_url, r.license, r.license_url, r.width, r.height, r.file_size_bytes, false,
               (SELECT COALESCE(MAX(w2.sort_order), -1) + 1 FROM wiki_images w2
                 WHERE w2.site_id = r.site_id),
               'wikimedia', true, false
        RETURNING id INTO new_id;

        IF r.new_thumbnail IS DISTINCT FROM r.old_thumbnail THEN
            UPDATE unified_sites SET thumbnail_url = r.new_thumbnail WHERE id = r.site_id;
        END IF;

        -- the journal, in this transaction: one row per column this statement wrote,
        -- read back from the row it created, so the journal records what the database holds
        INSERT INTO remediation_change_log
            (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value, change_key,
             confidence, evidence, site_id_ref)
        SELECT 'insert-2026-10-07-006-001', 'import-hero/insert/owner-2026-10-05', 'wiki_images', t.col, new_id::text, NULL, t.val,
               r.change_key || ':' || t.col, 'authoritative', r.evidence, r.site_id
          FROM wiki_images w
          CROSS JOIN LATERAL (VALUES
              ('filename', w.filename::text),
              ('original_url', w.original_url::text),
              ('commons_page_url', w.commons_page_url::text),
              ('title', w.title::text),
              ('author', w.author::text),
              ('author_url', w.author_url::text),
              ('license', w.license::text),
              ('license_url', w.license_url::text),
              ('width', w.width::text),
              ('height', w.height::text),
              ('file_size_bytes', w.file_size_bytes::text),
              ('is_lead', w.is_lead::text),
              ('sort_order', w.sort_order::text),
              ('source_type', w.source_type::text)
          ) AS t(col, val)
         WHERE w.id = new_id;

        IF r.demoted_id IS NOT NULL THEN
            INSERT INTO remediation_change_log
                (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value,
                 change_key, confidence, evidence, site_id_ref)
            VALUES ('insert-2026-10-07-006-001', 'import-hero/insert/owner-2026-10-05', 'wiki_images', 'is_hero',
                    r.demoted_id::text, 'true', 'false', r.change_key || ':demote',
                    'authoritative', r.evidence, r.site_id);
        END IF;

        IF r.new_thumbnail IS DISTINCT FROM r.old_thumbnail THEN
            INSERT INTO remediation_change_log
                (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value,
                 change_key, confidence, evidence, site_id_ref)
            VALUES ('insert-2026-10-07-006-001', 'import-hero/insert/owner-2026-10-05', 'unified_sites', 'thumbnail_url',
                    r.site_id::text, r.old_thumbnail, r.new_thumbnail,
                    r.change_key || ':thumbnail', 'authoritative', r.evidence, r.site_id);
        END IF;
    END LOOP;

    -- invariant 1: every planned row stands, with the planned values, the flag and the three
    -- columns the statement derived for it. The temp table is aliased `p`, never `r`: the loop
    -- variable of this block is `r`, and Postgres refuses a reference that could mean either
    -- (measured 2026-10-06, in the rehearsal of chunk-001).
    SELECT count(*) INTO bad FROM _ih_insert p
      LEFT JOIN wiki_images w ON w.site_id = p.site_id AND w.original_url = p.original_url
     WHERE w.id IS NULL OR w.is_hero IS NOT TRUE OR w.is_excluded IS NOT FALSE
        OR w.width IS DISTINCT FROM p.width OR w.height IS DISTINCT FROM p.height
        OR w.file_size_bytes IS DISTINCT FROM p.file_size_bytes
        OR w.filename IS DISTINCT FROM p.filename OR w.original_url IS DISTINCT FROM p.original_url
        OR w.is_lead IS NOT FALSE OR w.source_type IS DISTINCT FROM 'wikimedia'
        OR w.sort_order <> (SELECT COALESCE(MAX(w3.sort_order), 0) FROM wiki_images w3
                             WHERE w3.site_id = p.site_id);
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % inserted row(s) do not stand as planned', 'insert-2026-10-07-006-001', bad;
    END IF;

    -- invariant 2: at most one live hero per touched site (T09's invariant)
    SELECT count(*) INTO bad FROM (
        SELECT w.site_id FROM wiki_images w
          JOIN _ih_insert p ON p.site_id = w.site_id
         WHERE w.is_hero AND w.is_excluded IS NOT TRUE
         GROUP BY w.site_id HAVING count(*) > 1) d;
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % touched site(s) hold more than one live hero row',
            'insert-2026-10-07-006-001', bad;
    END IF;

    -- invariant 3: the journal carries every write, and nothing else
    SELECT count(*) INTO bad FROM _ih_insert p
      LEFT JOIN (SELECT site_id_ref, count(*) AS n FROM remediation_change_log
                  WHERE run_stamp = 'insert-2026-10-07-006-001' GROUP BY site_id_ref) l
        ON l.site_id_ref = p.site_id
     WHERE COALESCE(l.n, 0) <> 14
        + CASE WHEN p.demoted_id IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN p.new_thumbnail IS DISTINCT FROM p.old_thumbnail THEN 1 ELSE 0 END;
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % site(s) do not have exactly their planned journal rows',
            'insert-2026-10-07-006-001', bad;
    END IF;
END $$;

-- the same two read-back lines the shared writer ends with, so `--rehearse` recognises the run
SELECT 'journal rows for this run', count(*)::text FROM remediation_change_log WHERE run_stamp = 'insert-2026-10-07-006-001';
SELECT 'planned rows', count(*)::text FROM _ih_insert;
COMMIT;
